namespace Meziantou.Framework.PublicApiGenerator;

public sealed class PublicApiOptions
{
    public PublicApiFileLayout FileLayout { get; set; } = PublicApiFileLayout.SingleFile;

    public bool IncludeAutoGeneratedComment { get; set; } = true;

    /// <summary>
    /// Gets or sets a value indicating whether the header lists the simple names of the referenced assemblies, so that adding or removing a dependency shows up in the generated files.
    /// When the assembly has a <c>.deps.json</c> file, only the assemblies it lists (packages, project references and referenced files) are written, not the assemblies of the framework.
    /// Otherwise, every referenced assembly is written. <see cref="IncludedAssemblyReferences"/> and <see cref="ExcludedAssemblyReferences"/> change the list.
    /// When the target frameworks do not reference the same assemblies, the name of an assembly that only some of them reference is followed by these target frameworks.
    /// The default value is <see langword="false"/>.
    /// </summary>
    public bool IncludeAssemblyReferences { get; set; }

    /// <summary>
    /// Gets the patterns of the names of the framework assemblies to write when <see cref="IncludeAssemblyReferences"/> is <see langword="true"/> (e.g. <c>System.Net.*</c>).
    /// A pattern can contain <c>*</c> (any characters) and <c>?</c> (one character), and is compared without case.
    /// </summary>
    public IList<string> IncludedAssemblyReferences { get; } = [];

    /// <summary>
    /// Gets the patterns of the names of the assemblies not to write when <see cref="IncludeAssemblyReferences"/> is <see langword="true"/>.
    /// A pattern can contain <c>*</c> (any characters) and <c>?</c> (one character), and is compared without case. It wins over <see cref="IncludedAssemblyReferences"/>.
    /// </summary>
    public IList<string> ExcludedAssemblyReferences { get; } = [];
}
